/*
R03 run55 exact checker: new support-(3,6), overlap-two projective sign-relation planes.
Finite scope: binary m=10 reduction over F_11.
- Enumerate canonical 2-planes generated by support-3 and support-6 projective +/-1 lines overlapping in exactly two coordinates.
- Exclude every plane meeting collision support <=2, any old overlap-0/1 sign-line family, the run34 support-(3/4,3/4) overlap-two family, or the run35 support-(3,5) overlap-two family, or the current run55 support-(4,5) family.
- Compress each surviving 7-coordinate local rowspace, enumerate its Boolean orthogonal slice exactly, and compute its largest proper projective hyperplane fiber.
- Apply the retained greedy ordered-basis certificate for exact modular nullity 2, then the inherited conservative C253 slack 11-132/16105.
- Regress the exact aggregate E, normalized correction, and improved full-range n=11 remainder upper bound.
All certificate arithmetic is integer / finite-field exact.
*/
#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;
static const int M=10,P=11;
using V10=array<unsigned char,10>; using K20=array<unsigned char,20>; using K14=array<unsigned char,14>;
struct Line{V10 v; int mask;}; struct Cand{K20 key; int umask;};
int modinv(int a){for(int x=1;x<P;x++)if((a*x)%P==1)return x;abort();}
vector<Line> gen_lines(int s){vector<Line> out; vector<int> comb(s); function<void(int,int)> rec=[&](int pos,int start){if(pos==s){int mask=0;for(int i:comb)mask|=1<<i;int tails=1<<(s-1);for(int bits=0;bits<tails;bits++){V10 v{};v.fill(0);v[comb[0]]=1;for(int j=1;j<s;j++)v[comb[j]]=((bits>>(j-1))&1)?P-1:1;out.push_back({v,mask});}return;}for(int i=start;i<=M-(s-pos);i++){comb[pos]=i;rec(pos+1,i+1);}};rec(0,0);return out;}
K20 rref2(const V10&a,const V10&b){int A[2][M];for(int j=0;j<M;j++){A[0][j]=a[j];A[1][j]=b[j];}int r=0;for(int c=0;c<M&&r<2;c++){int piv=-1;for(int rr=r;rr<2;rr++)if(A[rr][c]%P){piv=rr;break;}if(piv<0)continue;if(piv!=r)for(int j=0;j<M;j++)swap(A[piv][j],A[r][j]);int inv=modinv(A[r][c]%P);for(int j=0;j<M;j++)A[r][j]=A[r][j]*inv%P;for(int rr=0;rr<2;rr++)if(rr!=r&&A[rr][c]){int f=A[rr][c];for(int j=0;j<M;j++){A[rr][j]=(A[rr][j]-f*A[r][j])%P;if(A[rr][j]<0)A[rr][j]+=P;}}r++;}if(r!=2)exit(2);K20 k{};for(int j=0;j<M;j++){k[j]=A[0][j];k[M+j]=A[1][j];}return k;}
int smask(const array<int,M>&u){int m=0;for(int i=0;i<M;i++)if(u[i]%P)m|=1<<i;return m;}
bool signrel(const array<int,M>&u){int first=-1;for(int x:u)if(x%P){first=x%P;break;}if(first<0)return false;int inv=modinv(first);for(int x:u)if(x%P){int y=x*inv%P;if(y!=1&&y!=P-1)return false;}return true;}
bool clean(const K20&k){array<int,M>v{},w{};for(int i=0;i<M;i++){v[i]=k[i];w[i]=k[M+i];}vector<pair<int,int>> infos;int mins=99;for(int tt=0;tt<=P;tt++){array<int,M>u{};if(tt<P){for(int i=0;i<M;i++)u[i]=(v[i]+tt*w[i])%P;}else u=w;int ma=smask(u),s=__builtin_popcount((unsigned)ma);mins=min(mins,s);if(signrel(u))infos.push_back({ma,s});}if(mins<=2)return false;for(int i=0;i<(int)infos.size();i++)for(int j=i+1;j<(int)infos.size();j++){int ov=__builtin_popcount((unsigned)(infos[i].first&infos[j].first));int a=min(infos[i].second,infos[j].second),b=max(infos[i].second,infos[j].second);if(ov<=1)return false;if(ov==2 && b<=4)return false;if(ov==2 && a==3 && b==5)return false;if(ov==2 && a==4 && b==5)return false;}return true;}
K14 localkey(const K20&k,int umask){vector<int>idx;for(int i=0;i<M;i++)if(umask>>i&1)idx.push_back(i);if(idx.size()!=7)exit(3);int A[2][7];for(int j=0;j<7;j++){A[0][j]=k[idx[j]];A[1][j]=k[M+idx[j]];}int r=0;for(int c=0;c<7&&r<2;c++){int piv=-1;for(int rr=r;rr<2;rr++)if(A[rr][c]){piv=rr;break;}if(piv<0)continue;if(piv!=r)for(int j=0;j<7;j++)swap(A[piv][j],A[r][j]);int inv=modinv(A[r][c]);for(int j=0;j<7;j++)A[r][j]=A[r][j]*inv%P;for(int rr=0;rr<2;rr++)if(rr!=r&&A[rr][c]){int f=A[rr][c];for(int j=0;j<7;j++){A[rr][j]=(A[rr][j]-f*A[r][j])%P;if(A[rr][j]<0)A[rr][j]+=P;}}r++;}if(r!=2)exit(4);K14 z{};for(int j=0;j<7;j++){z[j]=A[0][j];z[7+j]=A[1][j];}return z;}
int rank5(const vector<array<int,5>>&rows){auto A=rows;int r=0;for(int c=0;c<5;c++){int piv=-1;for(int i=r;i<(int)A.size();i++)if(A[i][c]%P){piv=i;break;}if(piv<0)continue;swap(A[piv],A[r]);int inv=modinv(A[r][c]);for(int j=0;j<5;j++)A[r][j]=A[r][j]*inv%P;for(int i=0;i<(int)A.size();i++)if(i!=r&&A[i][c]){int f=A[i][c];for(int j=0;j<5;j++){A[i][j]=(A[i][j]-f*A[r][j])%P;if(A[i][j]<0)A[i][j]+=P;}}r++;}return r;}
pair<int,int> stats(const K14&k){int row[2][7];for(int j=0;j<7;j++){row[0][j]=k[j];row[1][j]=k[7+j];}vector<int>piv;for(int r=0;r<2;r++){for(int j=0;j<7;j++)if(row[r][j]){piv.push_back(j);break;}}vector<int>fr;for(int j=0;j<7;j++)if(find(piv.begin(),piv.end(),j)==piv.end())fr.push_back(j);if(fr.size()!=5)exit(5);vector<array<int,5>>pts;int h=0;for(int bits=0;bits<128;bits++){int s0=0,s1=0;for(int j=0;j<7;j++){int b=(bits>>j)&1;s0+=row[0][j]*b;s1+=row[1][j]*b;}if(s0%P==0&&s1%P==0){h++;array<int,5>x{};for(int q=0;q<5;q++)x[q]=(bits>>fr[q])&1;pts.push_back(x);}}if(rank5(pts)<5)return {h,-1};int qmax=0; // projective forms normalized first nonzero=1
for(int first=0;first<5;first++){int rem=4-first;int total=1;for(int z=0;z<rem;z++)total*=P;for(int code=0;code<total;code++){int a[5]={0,0,0,0,0};a[first]=1;int tmp=code;for(int j=first+1;j<5;j++){a[j]=tmp%P;tmp/=P;}int cnt[P]={0};for(auto &x:pts){int s=0;for(int j=0;j<5;j++)s+=a[j]*x[j];cnt[s%P]++;}for(int rr=0;rr<P;rr++)qmax=max(qmax,cnt[rr]);}}
return {h,qmax};}
int main(){
 auto L3=gen_lines(3),L6=gen_lines(6);
 if(L3.size()!=480||L6.size()!=6720) return 10;
 vector<Cand> cs; cs.reserve(1800000);
 for(auto&a:L3)for(auto&b:L6) if(__builtin_popcount((unsigned)(a.mask&b.mask))==2) cs.push_back({rref2(a.v,b.v),a.mask|b.mask});
 if(cs.size()!=1612800){cerr<<"pairs "<<cs.size()<<"\n";return 11;}
 sort(cs.begin(),cs.end(),[](const Cand&A,const Cand&B){return A.key<B.key;});
 vector<Cand> uq; uq.reserve(cs.size()); for(auto&x:cs) if(uq.empty()||uq.back().key!=x.key) uq.push_back(x);
 if(uq.size()!=1612800){cerr<<"unique "<<uq.size()<<"\n";return 12;}
 map<K14,long long>lc; long long keep=0; for(auto&x:uq) if(clean(x.key)){keep++;lc[localkey(x.key,x.umask)]++;}
 if(keep!=806400||lc.size()!=6720){cerr<<"keep/types "<<keep<<" "<<lc.size()<<"\n";return 13;}
 map<string,long long> sum; long long pos=0,nosp=0; cpp_int E=0;
 for(auto&kv:lc){auto [hloc,q]=stats(kv.first);long long mult=kv.second;if(q<0){nosp+=mult;sum["nospan_h"+to_string(hloc)]+=mult;continue;}int h=hloc*8;int Q=max(q*8,h/2);cpp_int basis=1;bool ok=true;for(int j=0;j<8;j++){int f=h-min(1<<j,Q);if(f<=0)ok=false;basis*=f;}if(!ok||h<=M){sum["zero_h"+to_string(hloc)+"_q"+to_string(q)]+=mult;continue;}cpp_int tail=(h-M+1)*(h-M);E+=cpp_int(mult)*basis*tail;pos+=mult;sum["positive_h"+to_string(hloc)+"_q"+to_string(q)+"_H"+to_string(h)+"_Q"+to_string(Q)]+=mult;}
 if(pos!=453600||nosp!=352800||pos+nosp!=keep)return 14;
 cpp_int Eexp("3064688944446443618304000");if(E!=Eexp){cerr<<"E mismatch "<<E<<"\n";return 15;}
 map<string,long long> exp;exp["nospan_h1"]=50400;exp["nospan_h4"]=100800;exp["nospan_h5"]=126000;exp["nospan_h6"]=75600;exp["positive_h11_q10_H88_Q80"]=277200;exp["positive_h14_q10_H112_Q80"]=176400;
 if(sum!=exp){cerr<<"summary mismatch\n";return 16;}
 cpp_int slackN=177023,slackD=16105;cpp_int rawCN=slackN*E,rawCD=slackD*(cpp_int(1)<<89);
 cpp_int corrN("6467347514781269891775"),corrD("118833925322836931510272");if(rawCN*corrD!=corrN*rawCD)return 17;
 cpp_int baseN("32591619015762864326494406778135"),baseD("62303201039659529147657486336");
 cpp_int newN("32588228263069034684065387846935"),newD("62303201039659529147657486336");
 if((baseN*newD-newN*baseD)*corrD!=corrN*baseD*newD)return 18;
 cout<<"R03 RUN55 SUPPORT-(3,6) OVERLAP-TWO EXACT CHECK\n";
 cout<<"candidate generating pairs = "<<cs.size()<<"\nunique projective planes = "<<uq.size()<<"\nnew planes after collision + all prior sparse-family exclusions including support-(4,5) = "<<keep<<"\nlocal rowspace types = "<<lc.size()<<"\npositive exact-nullity-2 planes = "<<pos<<"\nno-span planes = "<<nosp<<"\nsummary:\n";for(auto&z:sum)cout<<"  "<<z.first<<" = "<<z.second<<"\n";
 cout<<"exact-corank-2 matrices lower bound E = "<<E<<"\nconservative C253 slack = 177023/16105\nnormalized correction = "<<corrN<<"/"<<corrD<<"\nintermediate r11 upper = "<<baseN<<"/"<<baseD<<"\nfinal r11 upper = "<<newN<<"/"<<newD<<"\nSELF-CHECK PASS\n";
}
